class DistanceLimitedPathsExist {
    vector<int> parent, depth, component;
    vector<vector<int>> up, mx;
    int LOG;
public:
    DistanceLimitedPathsExist(int n, vector<vector<int>>& edgeList) {
        vector<int> dsu(n), sz(n, 1);
        iota(dsu.begin(), dsu.end(), 0);
        function<int(int)> find = [&](int x) {
            return dsu[x] == x ? x : dsu[x] = find(dsu[x]);
        };
        sort(edgeList.begin(), edgeList.end(), [](const vector<int>& a, const vector<int>& b) {
            return a[2] < b[2];
        });
        vector<vector<pair<int,int>>> g(n);
        for (const auto& e : edgeList) {
            int a = find(e[0]), b = find(e[1]);
            if (a == b) continue;
            if (sz[a] < sz[b]) swap(a, b);
            dsu[b] = a;
            sz[a] += sz[b];
            g[e[0]].push_back({e[1], e[2]});
            g[e[1]].push_back({e[0], e[2]});
        }
        LOG = 1;
        while ((1LL << LOG) <= n) ++LOG;
        up.assign(LOG, vector<int>(n));
        mx.assign(LOG, vector<int>(n, 0));
        depth.assign(n, -1);
        component.resize(n);
        for (int root = 0; root < n; ++root) {
            if (depth[root] != -1) continue;
            queue<int> q;
            q.push(root);
            depth[root] = 0;
            component[root] = root;
            up[0][root] = root;
            while (!q.empty()) {
                int u = q.front(); q.pop();
                for (auto edge : g[u]) {
                    int v = edge.first;
                    if (depth[v] != -1) continue;
                    depth[v] = depth[u] + 1;
                    component[v] = root;
                    up[0][v] = u;
                    mx[0][v] = edge.second;
                    q.push(v);
                }
            }
        }
        for (int j = 1; j < LOG; ++j) {
            for (int v = 0; v < n; ++v) {
                up[j][v] = up[j - 1][up[j - 1][v]];
                mx[j][v] = max(mx[j - 1][v], mx[j - 1][up[j - 1][v]]);
            }
        }
    }
    bool query(int p, int q, int limit) {
        if (component[p] != component[q]) return false;
        int worst = 0;
        if (depth[p] < depth[q]) swap(p, q);
        int delta = depth[p] - depth[q];
        for (int j = 0; j < LOG; ++j) {
            if (delta & (1 << j)) {
                worst = max(worst, mx[j][p]);
                p = up[j][p];
            }
        }
        if (p != q) {
            for (int j = LOG - 1; j >= 0; --j) {
                if (up[j][p] != up[j][q]) {
                    worst = max(worst, max(mx[j][p], mx[j][q]));
                    p = up[j][p];
                    q = up[j][q];
                }
            }
            worst = max(worst, max(mx[0][p], mx[0][q]));
        }
        return worst < limit;
    }
};
